{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "A close afatinib-type 4-anilinoquinazoline with the same 3-chloro-4-fluoroaniline substituent showed good oral bioavailability in human Phase I studies, supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Simotinib, sharing the same quinazoline core and aniline group, was orally bioavailable in NSCLC patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Gefitinib, a 4-anilinoquinazoline EGFR inhibitor, has approximately 60% oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Erlotinib absolute oral bioavailability was 59% (95% CI 55-63%) in healthy volunteers, confirming high F for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Selatinib, a lapatinib-like analogue, showed high oral bioavailability in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Zongertinib, a related quinazoline EGFR inhibitor, was predicted to have 41% human oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Lenvatinib, a related quinazoline, has absolute bioavailability in the order of 85%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 4-anilinoquinazoline EGFR inhibitor closely related to afatinib. Multiple close analogues with the same core and aniline substituent (afatinib-type, simotinib, gefitinib, erlotinib, selatinib, zongertinib, lenvatinib) show oral bioavailability well above 20%, including absolute values of 59-85%. Distant low-F compounds are structurally unrelated and do not outweigh this consistent scaffold-level evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "Several supportive records are not explicitly absolute bioavailability determinations, though they consistently indicate high oral exposure.",
    "The piperidine-crotonamide side chain differs from afatinib's dimethylamino-crotonamide and could modestly alter absorption or first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

